import { useCallback, useState, type ChangeEvent, type KeyboardEvent } from 'react';
import { Input, Stack, Tag, Text } from '@jinx-ui/react';

export type TagPickerProps = {
  label?: string;
  placeholder?: string;
  initialTags?: string[];
  maxTags?: number;
  onChange?: (tags: string[]) => void;
};

function TagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  initialTags = [],
  maxTags = 10,
  onChange,
}: TagPickerProps) {
  const [tags, setTags] = useState<string[]>(initialTags);
  const [draft, setDraft] = useState('');

  const commit = useCallback(
    (next: string[]) => {
      setTags(next);
      onChange?.(next);
    },
    [onChange],
  );

  const addTag = useCallback(
    (raw: string) => {
      const tag = raw.trim().replace(/\s+/g, ' ');
      if (!tag || tags.length >= maxTags) return;
      if (tags.some((existing) => existing.toLowerCase() === tag.toLowerCase())) return;
      commit([...tags, tag]);
    },
    [commit, maxTags, tags],
  );

  const removeTag = useCallback(
    (tag: string) => {
      commit(tags.filter((existing) => existing !== tag));
    },
    [commit, tags],
  );

  const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
    const next = event.target.value;
    if (next.endsWith(',')) {
      addTag(next.slice(0, -1));
      setDraft('');
      return;
    }
    setDraft(next);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      addTag(draft);
      setDraft('');
      return;
    }
    if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      removeTag(tags[tags.length - 1]);
    }
  };

  const isFull = tags.length >= maxTags;

  return (
    <Stack direction="column" style={{ gap: 'var(--jx-space-2)' }}>
      <Input
        label={label}
        placeholder={isFull ? 'Достигнут лимит тегов' : placeholder}
        value={draft}
        disabled={isFull}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
        onBlur={() => {
          addTag(draft);
          setDraft('');
        }}
      />
      {tags.length > 0 ? (
        <Stack
          direction="row"
          wrap
          aria-label="Выбранные теги"
          style={{ gap: 'var(--jx-space-1)' }}
        >
          {tags.map((tag) => (
            <Tag key={tag} onRemove={() => removeTag(tag)}>
              {tag}
            </Tag>
          ))}
        </Stack>
      ) : (
        <Text size="sm" tone="muted">
          Теги пока не выбраны
        </Text>
      )}
      <Text size="sm" tone="muted">
        {tags.length} из {maxTags}
      </Text>
    </Stack>
  );
}

export default TagPicker;

